impl ar_world_tracking_provider_t {
    /// Query a device anchor at the given timestamp.
    ///
    /// The origin is a right-handed coordinate system and is defined such that X points to the right, Y points up, and Z points backward.
    ///
    /// Example usage:
    /// ```text
    /// auto timing_info = cp_drawable_get_frame_timing(drawable);
    /// auto time = cp_time_to_cf_time_interval(cp_frame_timing_get_presentation_time(timing_info));
    /// const ar_device_anchor_query_status_t status = ar_world_tracking_provider_query_device_anchor_at_timestamp(_provider, time,
    /// &device
    /// _anchor);
    /// ```
    ///
    /// - Note: This API is not thread safe.
    ///
    /// - Parameters:
    /// - world_tracking_provider: The world tracking provider.
    /// - timestamp: The timestamp to get the device anchor at. The timestamp should be provided as mach absolute time in seconds.
    /// - device_anchor: The output device anchor.
    ///
    /// - Returns: An `ar_device_anchor_query_status_t` value indicating whether the device anchor was successfully retrieved at the given timestamp or not.
    ///
    /// # Safety
    ///
    /// - `world_tracking_provider` must implement OS_ar_world_tracking_provider.
    /// - `device_anchor` must implement OS_ar_device_anchor.
    #[doc(alias = "ar_world_tracking_provider_query_device_anchor_at_timestamp")]
    #[cfg(all(
        feature = "anchor",
        feature = "data_provider",
        feature = "objc2",
        feature = "objc2-core-foundation"
    ))]
    #[inline]
    pub unsafe fn query_device_anchor_at_timestamp(
        world_tracking_provider: &ar_world_tracking_provider_t,
        timestamp: CFTimeInterval,
        device_anchor: &ar_device_anchor_t,
    ) -> ar_device_anchor_query_status_t {
        extern "C-unwind" {
            fn ar_world_tracking_provider_query_device_anchor_at_timestamp(
                world_tracking_provider: &ar_world_tracking_provider_t,
                timestamp: CFTimeInterval,
                device_anchor: &ar_device_anchor_t,
            ) -> ar_device_anchor_query_status_t;
        }
        unsafe {
            ar_world_tracking_provider_query_device_anchor_at_timestamp(
                world_tracking_provider,
                timestamp,
                device_anchor,
            )
        }
    }

    /// Get the authorization type required by the world tracking provider.
    ///
    /// - Returns: The required authorization type.
    #[doc(alias = "ar_world_tracking_provider_get_required_authorization_type")]
    #[cfg(feature = "authorization")]
    #[inline]
    pub unsafe fn required_authorization_type() -> ar_authorization_type_t {
        extern "C-unwind" {
            fn ar_world_tracking_provider_get_required_authorization_type(
            ) -> ar_authorization_type_t;
        }
        unsafe { ar_world_tracking_provider_get_required_authorization_type() }
    }
}
